# Let's decode source header encoding
def decode_header(s):
    m = re.match(r'=\?([^?]+)\?B\?([^?]+)\?=\s*<(.+)>', s)
    if m:
        charset, b64, addr = m.groups()
        try:
            decoded = base64.b64decode(b64).decode(charset)
        except:
            decoded = b64
        return decoded, addr
    m2 = re.match(r'=\?([^?]+)\?B\?([^?]*)\?=\s*<(.+)>', s)
    if m2:
        charset, b64, addr = m2.groups()
        if b64 == "":
            return "", addr
    return s, None

for i,o in enumerate(out):
    decoded, addr = decode_header(o['source'])
    print(f"OUT {i} decoded source name {decoded!r} addr {addr}")

for i,o in enumerate(out):
    rt = o['replyTo'][0] if o['replyTo'] else ""
    m = re.match(r'(.*)\s*<(.+)>', rt)
    if m:
        disp, addr2 = m.groups()
        m3 = re.match(r'=\?([^?]+)\?B\?([^?]+)\?=', disp.strip())
        if m3:
            charset, b64 = m3.groups()
            disp_dec = base64.b64decode(b64).decode(charset) if b64 else ""
        else:
            disp_dec = disp
        print(f"OUT {i} replyTo disp {disp_dec!r} addr {addr2!r} raw {rt!r}")
