  await sleep(2000);
  const out = fs.readFileSync(outboxPath,'utf-8').trim();
  const lines = out ? out.split('\n') : [];
  console.log(`\n=== OUTBOX after publish: ${lines.length} entries ===`);
  for (let i=0;i<lines.length;i++){
    const o = JSON.parse(lines[i]);
