  }

  // Verify expectations per task
  // One event must become one message addressed only to its named customer.
  // Means each data entry -> one SendEmail with single To.
  // Suppressed bounced@lattice-robotics.example should fail and not block others, and not fallback.
  const expectedTo = [];
  for (const ev of events){
    for (const d of ev.data){
      if (d.toEmail === 'bounced@lattice-robotics.example') continue; // suppressed should fail, not in outbox
      if (d.toEmail) expectedTo.push(d.toEmail);
    }
  }
  console.log("\nExpected To addresses (excluding suppressed bounced, empty data):", expectedTo);
  const actualTo = lines.map(l=>JSON.parse(l).to[0]);
  console.log("Actual To addresses:", actualTo);
  console.log("\nMatch?", JSON.stringify(expectedTo)===JSON.stringify(actualTo) ? "PASS" : "FAIL");
  if (JSON.stringify(expectedTo)!==JSON.stringify(actualTo)){
    console.log("Missing", expectedTo.filter(x=>!actualTo.includes(x)));
    console.log("Extra", actualTo.filter(x=>!expectedTo.includes(x)));
  }

  // Check wire conventions for a few entries vs capture
  // For html true => html charset UTF-8, text null and vice versa
  for (const line of lines){
    const o = JSON.parse(line);
    if (o.html && o.text) console.error("ERROR both html and text present", o);
    if (!o.html && !o.text) console.error("ERROR neither html nor text", o);
    if (o.configurationSet !== 'defaultConfigurationSet') console.error("ERROR config", o);
    if (!o.subject || o.subject.charset !== 'UTF-8') console.error("ERROR subject charset", o);
    if (o.html && o.html.charset !== 'UTF-8') console.error("ERROR html charset", o);
    if (o.text && o.text.charset !== 'UTF-8') console.error("ERROR text charset", o);
    // source should be encoded mime
    if (!o.source.includes('=?UTF-8?B?')) console.error("ERROR source not encoded", o.source);
  }
  console.log("\nWire checks done");

  // Check empty data event produced nothing (event 4)
  // Check that backup-ap succeeded even though same event had bounced failure
  if (actualTo.includes('backup-ap@lattice-robotics.example')) console.log("PASS backup-ap present despite bounced failure in same event");
  else console.log("FAIL backup-ap missing");

  if (actualTo.includes('finance@harbor-analytics.example')) console.log("PASS finance present");
  else console.log("FAIL finance missing");

  // Ensure no multi-recipient messages
  for (const line of lines){
    const o = JSON.parse(line);
    if (o.to.length !== 1) console.error("FAIL multi-recipient message", o);
  }
  console.log("Single recipient check done");

  // Ensure that suppressed bounced not in outbox
  if (actualTo.includes('bounced@lattice-robotics.example')) console.log("FAIL suppressed present");
  else console.log("PASS suppressed not present");

  // Ensure total count
  // events: 0:1,1:1,2:1,3:2,4:0,5:1 suppressed,6:1,7:2 (1 suppressed),8:1,9:1 => expected 9
  const expectedCount = 9;
  console.log(`Expected count ${expectedCount}, actual ${lines.length} => ${lines.length===expectedCount?'PASS':'FAIL'}`);
}
main().catch(e=>{console.error(e); process.exit(1)});
